import scala.io.Source
object PropertiesCheck{def main(a:Array[String]):Unit={if(a.isEmpty||a(0)=="--help"){println("Usage: properties-check FILE");if(a.isEmpty)sys.exit(2);return};var seen=Set[String]();var dup=0;var malformed=0;var entries=0;for((l,i)<-Source.fromFile(a(0)).getLines().zipWithIndex){val s=l.trim;if(s.nonEmpty && !s.startsWith("#") && !s.startsWith("!")){val p=s.indexOf('=');if(p<1)malformed+=1 else{val k=s.substring(0,p).trim;entries+=1;if(seen(k))dup+=1;seen+=k}}};println(s"entries=$entries");println(s"unique_keys=${seen.size}");println(s"duplicate_keys=$dup");println(s"malformed_lines=$malformed")}}
